#[cfg(test)]
mod tests {
    use super::*;

    const ALL: &[Icon] = &[
        Icon::Shield,
        Icon::ShieldCheck,
        Icon::ShieldAlert,
        Icon::Home,
        Icon::Wrench,
        Icon::Sparkles,
        Icon::Toolbox,
        Icon::History,
        Icon::Settings,
        Icon::Check,
        Icon::CheckCircle,
        Icon::X,
        Icon::AlertTriangle,
        Icon::Info,
        Icon::Refresh,
        Icon::Undo,
        Icon::ChevronRight,
        Icon::ChevronDown,
        Icon::Lock,
        Icon::Key,
        Icon::Download,
        Icon::Scan,
        Icon::Bug,
        Icon::Trash,
        Icon::Package,
        Icon::ExternalLink,
        Icon::Restart,
        Icon::Gamepad,
        Icon::Bot,
        Icon::Globe,
        Icon::Sun,
        Icon::Bell,
        Icon::Eye,
        Icon::EyeOff,
        Icon::Apps,
        Icon::Search,
        Icon::HardDrive,
        Icon::Moon,
        Icon::Password,
    ];

    #[test]
    fn every_icon_is_tintable_svg() {
        for &i in ALL {
            for b in [i.svg(), i.svg_filled()] {
                let s = std::str::from_utf8(b).unwrap();
                assert!(s.starts_with("<svg") && s.ends_with("</svg>"), "{i:?}");
                assert!(s.contains("currentColor"), "{i:?} not tintable");
                assert!(!s.contains("#212121"), "{i:?} hard-coded fill");
            }
        }
        assert!(std::str::from_utf8(BRAND_SVG)
            .unwrap()
            .contains("currentColor"));
    }

    #[test]
    fn filled_differs_from_regular() {
        for &i in ALL {
            assert_ne!(i.svg(), i.svg_filled(), "{i:?}");
        }
    }
}
